<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Authorization,Audit};
final class ExtendedMigrations {
 public static function files():array {$a=glob(APP_ROOT.'/database/modules/training_complete/*.{sql,php}',GLOB_BRACE);sort($a);return $a;}
 public static function plan(\PDO $p):array {if(!Migrations::ready($p))throw new \RuntimeException('T1 prerequisite belum lengkap.');$a=[];foreach(self::files() as $f){$v='training:FULL:'.basename($f);$r=Database::query($p,'SELECT * FROM database_migrations WHERE version=?',[$v])->fetch();if($r&&($r['status']!=='applied'||!hash_equals($r['checksum'],hash_file('sha256',$f))))throw new \RuntimeException('Partial migration/checksum drift: STOP dan restore terancang.');if(!$r&&str_ends_with($f,'.sql')){preg_match_all('/CREATE TABLE ([a-z_]+)/',file_get_contents($f),$matches);foreach($matches[1] as $table)if(Database::query($p,'SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$table])->fetchColumn())throw new \RuntimeException('Existing untracked table: '.$table.'. STOP dan reconcile schema.');}$a[]=['version'=>$v,'status'=>$r?'applied':'pending'];}return $a;}
 public static function ready(\PDO $p):bool {try{foreach(self::plan($p) as $r)if($r['status']!=='applied')return false;foreach(['training_sessions','training_checkpoints','training_attendance_tokens','training_attendance_events','training_attendance_corrections','training_cpd_rules','training_cpd_records','training_evaluations','training_evaluation_answers','core_signatories','training_templates','training_outputs','training_output_history','training_acknowledgements','core_content'] as $t)if(!Database::query($p,'SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$t])->fetchColumn())return false;return Database::query($p,"SELECT setting_value FROM system_settings WHERE setting_key='training_full_version'")->fetchColumn()==='1.0.0';}catch(\Throwable $e){return false;}}
 public static function require(\PDO $p):void {if(!self::ready($p))throw new \RuntimeException('Setup T2–T6 belum lengkap.');}
 public static function apply(\PDO $p,int $u):void {if(!Authorization::super($p,$u))throw new \RuntimeException('Super Admin diperlukan.');if((int)Database::query($p,"SELECT GET_LOCK(CONCAT('ep_full_',LEFT(SHA2(DATABASE(),256),40)),5)")->fetchColumn()!==1)throw new \RuntimeException('Migration sedang berjalan.');try{self::plan($p);foreach(self::files() as $f){$v='training:FULL:'.basename($f);if(Database::query($p,'SELECT 1 FROM database_migrations WHERE version=?',[$v])->fetchColumn())continue;Database::query($p,"INSERT INTO database_migrations(version,checksum,status) VALUES(?,?,'started')",[$v,hash_file('sha256',$f)]);if(str_ends_with($f,'.sql'))$p->exec(file_get_contents($f));else($fn=require $f)($p);Database::query($p,"UPDATE database_migrations SET status='applied',applied_at=UTC_TIMESTAMP() WHERE version=?",[$v]);}Database::query($p,"INSERT INTO system_settings(setting_key,setting_value) VALUES('training_full_version','1.0.0') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");Audit::record($p,'training.full_migrated',$u,null,'T2-T6','training');}finally{Database::query($p,"SELECT RELEASE_LOCK(CONCAT('ep_full_',LEFT(SHA2(DATABASE(),256),40)))");}}
}
